const unwrapped = args => Array.isArray(args[0]) ? args[0] : args

export const val = (v) => ({ val: v })
export const ref = (r) => ({ ref: String(r).split('.') })
export const expr = (x) => {
  if (Array.isArray(x)) return { list: x.map(expr) }
  if (x && typeof x === 'object') return x //> already a cxn object
  else return val(x)
}

export const subject = (x,pk) => {
  if (x.ref) return x
  if (x.name) return Object.defineProperty ({ref:[x.name]},'target',{value:x})
  let ref = [ !pk ? x : { id:x, where: where(pk) } ]
  return {ref}
}

export const columns = (...args) => {
  return unwrapped(args) .map (a => typeof a === 'string' ? ref(a) : val(a))
}

export const values = (...args) => {
  return unwrapped(args) .map (expr)
}

export const where = (x) => {
  if (!x || typeof x !== 'object') return [ val(x) ]
  return Object.entries(x) .map (([k,v]) => ['and', ref(k), '=', val(v)])
  .flat().slice(1)
}

export const having = where
export const groupBy = columns
export const orderBy = (...args) => {
  // orderBy({ a:1, b:-1 })
  if (typeof (args = unwrapped(args))[0] === 'object')
    return Object.entries(args[0]) .map (
      ([k,v]) => ({ ref:[k], sort: { [1]:'asc',[-1]:'desc' }[v] || v })
    )
  // orderBy('a desc','b')
  else return args.map (ordering_term => {
    const [,c,ad] = /^([^\s]+)(?:\s+(asc|desc))?$/i .exec (ordering_term)
    const ref = { ref: c.split('.') }
    if (ad) ref.sort = ad.toLowerCase()
    return ref
  })
}
